e3 = {
  const rng = d3.randomLcg(500 + e3_batch);
  const rn = d3.randomNormal.source(rng)(0, 1);
  const K = 200, maxN = e3_max, step = e3_step;
  let everSig = 0, finalSig = 0;
  const paths = [];
  for (let k = 0; k &lt; K; k++) {
    let sa = 0, sb = 0, ever = false, p = 1;
    const path = [];
    for (let n = 1; n &lt;= maxN; n++) {
      sa += rn(); sb += rn();
      if (n % step === 0) {
        const z = (sa / n - sb / n) / Math.sqrt(2 / n);
        p = 2 * (1 - pnorm(Math.abs(z)));
        if (p &lt; 0.05) ever = true;
        if (k &lt; 25) path.push({test: k, n, p, ever: false});
      }
    }
    if (ever) everSig++;
    if (p &lt; 0.05) finalSig++;
    if (k &lt; 25) { const e = path.some(d =&gt; d.p &lt; 0.05); path.forEach(d =&gt; d.ever = e); paths.push(...path); }
  }
  return {paths, everSig, finalSig, K};
}







